			return 2
		}
		return 1
	}

	oxbind.Boot()
	spec, carried := oxbind.Read(code)
	if !carried {
		// A card added after this mill was cast is not carried. Do not damage a
		// successful readout produced by an earlier invocation.
		return 1
	}

	slots := make(map[string]string, len(spec.Slots))
	for _, name := range spec.Slots {
		slots[name] = vals[name]
	}
	if writeJSON(outPath, map[string]any{"code": code, "slots": slots}) != nil {
		return 2
	}
	return 0
}

func writeJSON(path string, doc map[string]any) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	raw, err := json.MarshalIndent(doc, "", "  ")
	if err != nil {
		return err
	}
	raw = append(raw, '\n')
	tmp, err := os.CreateTemp(filepath.Dir(path), ".readout-*")
	if err != nil {
		return err
	}
	tmpName := tmp.Name()
	defer os.Remove(tmpName)
	if err = tmp.Chmod(0o644); err == nil {
		_, err = tmp.Write(raw)
	}
	if closeErr := tmp.Close(); err == nil {
		err = closeErr
	}
	if err != nil {
		return err
	}
	return os.Rename(tmpName, path)
}

func parseLamp(path string) (string, map[string]string, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return "", nil, err
	}
	code := ""
	vals := map[string]string{}
	for _, line := range strings.Split(string(raw), "\n") {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		if strings.HasPrefix(line, "CODE ") {
			code = strings.TrimSpace(strings.TrimPrefix(line, "CODE "))
			continue
		}
		if k, v, ok := strings.Cut(line, "="); ok {
			vals[strings.TrimSpace(k)] = strings.TrimSpace(v)
		}
	}
	if code == "" {
		return "", nil, errors.New("lamp has no code")
	}
	return code, vals, nil
}

type card struct {
